<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Admission Payments</h2><form method="get"><select name="status" class="form-control" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['pending','paid','rejected','failed','refunded'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></form></div><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Application</th><th>Fee</th><th>Gateway</th><th>Amount</th><th>Reference</th><th>Proof</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><?= esc($p->application_no) ?><br><?= esc($p->student_name) ?><br><small><?= esc($p->school_name) ?></small></td><td><?= esc(ucwords(str_replace('_',' ',$p->payment_type))) ?></td><td><?= esc(ucfirst($p->gateway?:'manual')) ?></td><td><?= esc($p->currency) ?> <?= number_format($p->amount,2) ?></td><td><?= esc($p->transaction_id) ?></td><td><?php if($p->proof_file): ?><a target="_blank" href="<?= base_url('school/admission/payments/'.$p->token.'/proof') ?>">Open receipt</a><?php else: ?>—<?php endif ?></td><td><?= esc(ucfirst($p->status)) ?><?php if($p->rejection_reason): ?><br><small><?= esc($p->rejection_reason) ?></small><?php endif ?></td><td><?php if($p->status==='pending'&&($p->gateway?:'manual')==='manual'): ?><?= form_open('school/admission/payments/'.$p->token.'/review') ?><input class="form-control form-control-sm mb-1" name="reason" placeholder="Reason if rejected"><button name="decision" value="paid" class="btn btn-sm btn-success">Verify</button> <button name="decision" value="rejected" class="btn btn-sm btn-danger">Reject</button><?= form_close() ?><?php elseif($p->status==='pending'): ?>Awaiting provider<?php else: ?>Reviewed<?php endif ?></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="8" class="text-center text-muted">No payment submissions.</td></tr><?php endif ?></tbody></table></div></div></div>
